x_comment(x_UniversityOfManchester,"#$UniversityOfManchester was first established in 1851 as Owens College (named after the textile merchant John Owens).  The College was granted a Royal Charter in April 1880 as the Victoria University, a federal institution which established colleges in Leeds and Liverpool. These Colleges were granted their independence in 1903 becoming the Universities of Leeds and Liverpool respectively, and creating the Victoria University of Manchester.  In October 2004, #$UniversityOfManchester will merge with #$UMIST to form the University of Manchester.") :- x_cid(a65b127fa71a12).
