x_comment(x_UMIST,"#$UMIST was founded on 7 April 1824 in the Bridgewater Arms, a Manchester pub, as the Manchester Mechanics' Institute.  In 1902, the school was renamed the Municipal School of Technology and in 1918 the Manchester Municipal College of Technology.  In 1956, its Royal Charter was granted, establishing the Manchester College of Science and Technology.  In 1966, the title University of Manchester Institute of Science and Technology was adopted.  In October 2004, #$UMIST will merge with #$UniversityOfManchester to form the University of Manchester.") :- x_cid(a65b127fa71a16).
